# GET /api/sheets/{sheetId}/statements — for each person on the sheet with a statement: how many were
# taken, and the last one's due-total and date.
respond:
  class: net.officefloor.hq.app.statement.RespondWithStatements
  govern: [ readonly-transaction ]
package net.officefloor.hq.app.statement;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** For each person on the sheet with a statement: their statement count and their last statement. */
public class RespondWithStatements {
    public void respond(@PathVariable("sheetId") String sheetId, StatementRepository statements,
            ObjectResponse<List<StatementSummary>> response) {
        response.send(statements.summaries(sheetId.trim()));
    }
}
handle:
  class: net.officefloor.hq.app.person.HandleInvalidPerson
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A person's statements: how many were taken, and the last one's due-total (two decimals, or n/a) and date
 *  (yyyy-MM-dd, the sheet's today when it was taken). A person with none has no entry. */
export type StatementSummary = { personId: number; count: number; dueTotal: string; date: string };

export const statementsKey = (sheetId: string) => ['sheet', sheetId, 'statements'];

/** Each person's statements on the sheet. */
export function useStatements(sheetId: string) {
  return useQuery({
    queryKey: statementsKey(sheetId),
    queryFn: () => getJson<StatementSummary[]>(`/api/sheets/${encodeURIComponent(sheetId)}/statements`),
  });
}
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import type { Person } from '../people/people';
import { claimsKey } from '../claims/claims';
import { statementsKey, useStatements } from './statements';

function StatementsHead() {
  return (
    <>
      <th>Statements</th>
      <th>Stated total</th>
      <th>Stated on</th>
      <th />
    </>
  );
}

/** A person's statement count, their last statement's due-total and date, and the button that takes one: it
 *  records their due-total now and binds each of their claims that counts to the figure it has now. */
function PersonStatements({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const statements = useStatements(sheetId);
  const queryClient = useQueryClient();
  const mine = statements.data?.find((s) => s.personId === person.id);
  const take = useMutation({
    mutationFn: () =>
      postJson(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/statements`, { by: user }),
    onSuccess: () =>
      Promise.all([
        queryClient.invalidateQueries({ queryKey: statementsKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      ]),
  });

  return (
    <>
      <td data-testid="person-statement-count">{mine?.count ?? 0}</td>
      <td data-testid="person-stated-total">{mine?.dueTotal ?? ''}</td>
      <td data-testid="person-statement-date">{mine?.date ?? ''}</td>
      <td>
        <button
          type="button"
          data-testid="person-statement"
          disabled={take.isPending}
          onClick={() => {
            take.reset();
            take.mutate();
          }}
        >
          Statement
        </button>
        {take.isError && <span data-testid="person-error"> Could not take a statement for this person.</span>}
      </td>
    </>
  );
}

export const contributions = [
  PeopleHead.fill({ order: 30, Component: StatementsHead }),
  PersonRow.fill({ order: 30, Component: PersonStatements }),
];

